content:
Terraform declaration order does not create a dependency cycle: an output may safely reference a resource declared earlier or later. The relevant issue is consistently addressing a resource created with `for_each`.

Use one environment per Terraform state/workspace so dev and prod remain independently deployable.

### `main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

locals {
  default_instance_classes = {
    dev  = "db.t3.micro"
    prod = "db.t3.medium"
  }

  instance_class = coalesce(
    var.instance_class,
    local.default_instance_classes[var.env]
  )

  # A single-key map gives the resource a stable environment key while
  # retaining for_each semantics.
  selected_environment = {
    (var.env) = {
      instance_class = local.instance_class
      multi_az       = var.env == "prod"
      encrypted      = var.env == "prod"
    }
  }
}

resource "aws_db_instance" "main" {
  for_each = local.selected_environment

  identifier        = "${each.key}-db"
  allocated_storage = 20
  engine            = "postgres"
  engine_version    = "16.1"
  instance_class    = each.value.instance_class

  db_name  = var.db_name
  username = var.db_user
  password = var.db_password

  multi_az          = each.value.multi_az
  storage_encrypted = each.value.encrypted

  publicly_accessible    = false
  backup_retention_period = 7
  deletion_protection     = true

  # If deletion protection is deliberately disabled later, require a final
  # snapshot rather than silently deleting the database.
  skip_final_snapshot       = false
  final_snapshot_identifier = "${each.key}-db-final"

  lifecycle {
    precondition {
      condition     = each.key != "prod" || each.value.multi_az
      error_message = "The production database must be multi-AZ."
    }

    precondition {
      condition     = each.key != "prod" || each.value.encrypted
      error_message = "The production database must be encrypted."
    }
  }
}

output "db_endpoint" {
  description = "Endpoint for the database in the selected environment."
  value       = aws_db_instance.main[var.env].endpoint
}

variable "region" {
  description = "AWS region for the selected environment."
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment deployed by this state."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.env)
    error_message = "env must be either dev or prod."
  }
}

variable "instance_class" {
  description = "Optional override for the environment's RDS instance class."
  type        = string
  default     = null
  nullable    = true
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_user" {
  type    = string
  default = "app_user"
}

variable "db_password" {
  description = "RDS master password supplied through an encrypted var file or secret manager."
  type        = string
  sensitive   = true
}
```

### `dev.tfvars`

```hcl
env    = "dev"
region = "us-east-1"

# Supply db_password separately from an encrypted SOPS file or TF_VAR_db_password.
```

### `prod.tfvars`

```hcl
env    = "prod"
region = "us-east-1"

# Supply db_password separately from an encrypted SOPS file or TF_VAR_db_password.
```

Deploy each environment with a separate workspace/state:

```bash
terraform workspace select dev || terraform workspace new dev
terraform apply -var-file=dev.tfvars

terraform workspace select prod || terraform workspace new prod
terraform apply -var-file=prod.tfvars
```

Important points:

- `count` and `var.envs` are removed; the resource now uses a keyed `for_each`.
- A `for_each` resource must be addressed by key:  
  `aws_db_instance.main[var.env].endpoint`, not `[0]`.
- The output reference is not circular; outputs are downstream graph nodes.
- `sensitive = true` only redacts CLI output. The password still exists in Terraform state, so the backend must use encryption and restricted access.
- Existing `count`-based state may need migration before applying, for example:

```bash
terraform state mv \
  'aws_db_instance.main[0]' \
  'aws_db_instance.main["dev"]'
```

Use `"prod"` instead if the existing state is the production state.
